result:
.ranking{
	background-color: #fff;
	overflow: hidden;
	.header{
		padding: 0 10px;
		height: 48px;
		img {
			width: 51px;
			height: 16px;
			display: block;
		}
	}
	.list{
		flex-wrap: nowrap;
		overflow: hidden;
		padding: 0 0 15px 10px;
		&.on{
			display: inline-flex;
			.item{
				width: 252px;
				height: 233px;
				display: inline-block;
				.name{
					font-size: 13px;
					color: #282828;
					margin-top: 8px;
				}
				.price{
					font-size: 14px;
					font-weight: 600;
					color: #E93323;
					.label{
						font-size: 10px;
					}
				}
				.yprice{
					color: #999999;
					font-size: 10px;
					text-decoration: line-through;
					margin-left: 4px;
				}
				.title{
					font-size: 13px;
					height: 33px;
				}
				.pictrue{
					width: 148px;
					height: 148px;
					background: #F3F9FF;
					border-radius: 4px;
					position: relative;

					img {
						width: 65px;
						height: 50px;
						display: block;
					}

					.img{
						width: 36px;
						height: 36px;
						display: block;
						position: absolute;
						top:0;
						left:0
					}
				}
				.picList{
					margin-left: 6px;
					.picItem{
						width: 71px;
						height: 71px;
						background: #F3F9FF;
						border-radius: 4px;
						position: relative;
						img {
							width: 44px;
							height: 34px;
							display: block;
						}
						.img {
							width: 24px;
							height: 24px;
							display: block;
							position: absolute;
							top:0;
							left:0
						}
						&~.picItem{
							margin-top: 6px;
						}
					}
				}
			}
		}
		.item{
			width: 186px;
			height: 241px;
			background: #FCEAE9;
			border-radius: 8px;
			padding: 0 8px 9px 8px;
			margin-right: 10px;
			.title{
				font-size: 14px;
				font-weight: 600;
				color: #E93323;
				height: 40px;
				.iconfont{
					font-size: 13px;
					margin-right: 4px;
				}
			}
			.listCon{
				width: 170px;
				height: 192px;
				background: #FFFFFF;
				border-radius: 6px;
				padding: 7px;
				.itemCon{
					&~.itemCon{
						margin-top: 8px;
					}
					.pictrue{
						width: 54px;
						height: 54px;
						background: #F3F9FF;
						margin-right: 8px;
						position: relative;
						img {
							width: 36px;
							height: 28px;
							display: block;
						}
						.img{
							width: 15px;
							height: 16px;
							display: block;
							position: absolute;
							top:0;
							left:0;
						}
					}
					.right{
						font-size: 13px;
						color: #333333;
						.price{
							font-weight: 600;
							color: #E93323;
							font-size: 14px;
							.lable{
								font-size: 10px;
							}
						}
					}
				}
			}
		}
	}
}
